@use "functions/defaults" as *;
@use "mixins/border-radius" as *;
@use "mixins/tokens" as *;
@use "mixins/transition" as *;
@use "config" as *;

// stylelint-disable custom-property-no-missing-var-function

// scss-docs-start toast-variables
$toast-max-width:                   350px !default;
$toast-padding-x:                   .75rem !default;
$toast-padding-y:                   .5rem !default;
$toast-font-size:                   .875rem !default;
$toast-color:                       var(--#{$prefix}fg-body) !default;
$toast-background-color:            var(--#{$prefix}bg-body) !default;
$toast-border-width:                var(--#{$prefix}border-width) !default;
$toast-border-color:                var(--#{$prefix}border-color-translucent) !default;
$toast-border-radius:               var(--#{$prefix}radius-7) !default;
$toast-box-shadow:                  var(--#{$prefix}box-shadow) !default;
$toast-spacing:                     $container-padding-x !default;
$toast-transition-property:         "opacity, display" !default;
$toast-transition-duration:         .15s !default;
$toast-transition-timing:           linear !default;

$toast-header-color:                var(--#{$prefix}fg-3) !default;
$toast-header-background-color:     $toast-background-color !default;
$toast-header-border-color:         $toast-border-color !default;
// scss-docs-end toast-variables

// scss-docs-start toast-translucent-variables
$toast-translucent-bg-opacity:      85% !default;
$toast-translucent-backdrop-filter: blur(5px) saturate(180%) !default;
// scss-docs-end toast-translucent-variables

$toast-tokens: () !default;

// stylelint-disable scss/dollar-variable-default

// scss-docs-start toast-css-vars
$toast-tokens: defaults(
  (
    --#{$prefix}toast-zindex: var(--#{$prefix}z-toast),
    --#{$prefix}toast-padding-x: #{$toast-padding-x},
    --#{$prefix}toast-padding-y: #{$toast-padding-y},
    --#{$prefix}toast-spacing: #{$toast-spacing},
    --#{$prefix}toast-max-width: #{$toast-max-width},
    --#{$prefix}toast-color: #{$toast-color},
    --#{$prefix}toast-bg: #{$toast-background-color},
    --#{$prefix}toast-border-width: #{$toast-border-width},
    --#{$prefix}toast-border-color: #{$toast-border-color},
    --#{$prefix}toast-border-radius: #{$toast-border-radius},
    --#{$prefix}toast-box-shadow: #{$toast-box-shadow},
    --#{$prefix}toast-header-color: #{$toast-header-color},
    --#{$prefix}toast-header-bg: #{$toast-header-background-color},
    --#{$prefix}toast-header-border-color: #{$toast-header-border-color},
    --#{$prefix}toast-font-size: $toast-font-size,
    --#{$prefix}toast-transition-property: #{$toast-transition-property},
    --#{$prefix}toast-transition-duration: #{$toast-transition-duration},
    --#{$prefix}toast-transition-timing: #{$toast-transition-timing},
  ),
  $toast-tokens
);
// scss-docs-end toast-css-vars

// stylelint-enable scss/dollar-variable-default
@layer components {
  .toast {
    @include tokens($toast-tokens);

    display: none;
    width: var(--#{$prefix}toast-max-width);
    max-width: 100%;
    font-size: var(--#{$prefix}toast-font-size);
    color: var(--#{$prefix}toast-color);
    pointer-events: auto;
    background-color: var(--#{$prefix}toast-bg);
    background-clip: padding-box;
    border: var(--#{$prefix}toast-border-width) solid var(--#{$prefix}theme-border, var(--#{$prefix}toast-border-color));
    box-shadow: var(--#{$prefix}toast-box-shadow);
    @include border-radius(var(--#{$prefix}toast-border-radius));

    // `display` is what makes a toast appear, and it cannot be interpolated, so
    // `allow-discrete` keeps it laid out until the fade-out finishes. Add
    // `.toast-instant` to skip the animation.
    &:not(.toast-instant) {
      opacity: 0;
      @include transition-props(
        var(--#{$prefix}toast-transition-property),
        var(--#{$prefix}toast-transition-duration),
        var(--#{$prefix}toast-transition-timing),
        allow-discrete
      );
    }

    &.show {
      display: block;
      opacity: 1;
    }
  }

  // The toast is not rendered before `.show` lands, so the fade-in needs an
  // explicit state to animate FROM: the base rule cannot express it.
  @starting-style {
    .toast:not(.toast-instant).show {
      opacity: 0;
    }
  }

  .toast-container {
    --#{$prefix}toast-zindex: var(--#{$prefix}z-toast);

    position: absolute;
    z-index: var(--#{$prefix}toast-zindex);
    width: max-content;
    max-width: 100%;
    pointer-events: none;

    > :not(:last-child) {
      margin-bottom: var(--#{$prefix}toast-spacing);
    }
  }

  .toast-header {
    display: flex;
    align-items: center;
    padding: var(--#{$prefix}toast-padding-y) var(--#{$prefix}toast-padding-x);
    color: var(--#{$prefix}theme-fg-emphasis, var(--#{$prefix}toast-header-color));
    background-color: var(--#{$prefix}theme-bg-subtle, var(--#{$prefix}toast-header-bg));
    background-clip: padding-box;
    border-block-end: var(--#{$prefix}toast-border-width) solid var(--#{$prefix}theme-border, var(--#{$prefix}toast-header-border-color));
    @include border-top-radius(calc(var(--#{$prefix}toast-border-radius) - var(--#{$prefix}toast-border-width)));

    .btn-close {
      margin-inline: var(--#{$prefix}toast-padding-x) calc(-.5 * var(--#{$prefix}toast-padding-x));
    }
  }

  .toast-body {
    padding: var(--#{$prefix}toast-padding-x);
    word-wrap: break-word;
  }

  .toast-translucent {
    background-color: color-mix(in oklch, var(--#{$prefix}toast-bg) #{$toast-translucent-bg-opacity}, transparent);
    backdrop-filter: $toast-translucent-backdrop-filter;

    .toast-header {
      background-color: color-mix(in oklch, var(--#{$prefix}theme-bg-subtle, var(--#{$prefix}toast-header-bg)) #{$toast-translucent-bg-opacity}, transparent);
    }
  }
}
